class Solution {
public:
    bool isCircularSentence(std::string sentence) {
        if (sentence.front() != sentence.back()) return false;
        int n = sentence.size();
        for (int i = 0; i < n; ++i) {
            if (sentence[i] == ' ' && sentence[i - 1] != sentence[i + 1]) return false;
        }
        return true;
    }
};

class Solution {
    public boolean isCircularSentence(String sentence) {
        if (sentence.charAt(0) != sentence.charAt(sentence.length() - 1)) return false;
        for (int i = 0; i < sentence.length(); i++) {
            if (sentence.charAt(i) == ' ' && sentence.charAt(i - 1) != sentence.charAt(i + 1)) return false;
        }
        return true;
    }
}

var isCircularSentence = function(sentence) {
    if (sentence[0] !== sentence[sentence.length - 1]) return false;
    for (let i = 0; i < sentence.length; i++) {
        if (sentence[i] === ' ' && sentence[i - 1] !== sentence[i + 1]) return false;
    }
    return true;
};
